"use client";
import Link from "next/link";
import { useState } from "react";
import { api } from "./api";
import { Button, Field, inputClass, Notice } from "./ui";

export function AuthForm({ mode, next, email: presetEmail }: { mode: "login" | "signup"; next: string; email?: string }) {
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  async function submit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    setBusy(true); setError("");
    try {
      await api(`/api/auth/${mode}`, { body: { email: f.get("email"), password: f.get("password"), ...(mode === "signup" ? { name: f.get("name") } : {}) } });
      // Full navigation so every server component sees the new session.
      window.location.assign(next.startsWith("/") && !next.startsWith("//") ? next : "/app");
    } catch (err) {
      setError((err as Error).message);
      setBusy(false);
    }
  }

  return (
    <form onSubmit={submit} className="space-y-4">
      {mode === "signup" && <Field label="Your name"><input name="name" required minLength={2} maxLength={80} autoComplete="name" className={inputClass} /></Field>}
      <Field label="Email"><input name="email" type="email" required defaultValue={presetEmail} autoComplete="email" className={inputClass} /></Field>
      <Field label="Password" hint={mode === "signup" ? "At least 10 characters." : undefined}>
        <input name="password" type="password" required minLength={mode === "signup" ? 10 : 1} autoComplete={mode === "signup" ? "new-password" : "current-password"} className={inputClass} />
      </Field>
      {error && <Notice tone="error">{error}</Notice>}
      <Button type="submit" disabled={busy} className="w-full">{busy ? "One moment…" : mode === "signup" ? "Create account" : "Sign in"}</Button>
      <p className="text-center text-[15px] text-ink-soft">
        {mode === "signup" ? "Already have an account? " : "New here? "}
        <Link className="font-semibold text-brand" href={`${mode === "signup" ? "/login" : "/signup"}?next=${encodeURIComponent(next)}`}>{mode === "signup" ? "Sign in" : "Create an account"}</Link>
      </p>
    </form>
  );
}
